using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Web.Script.Serialization;
namespace PZ3D {static class AddonTests {
 static void Check(bool ok,string n){if(!ok)throw new Exception("FAIL "+n);}
 public static void Run(){Type t=typeof(Program).Assembly.GetType("PZ3D.ViewpointAddons");Check(t!=null,"optional addon manager exists");var build=t.GetMethod("BuildDefault");Func<string,string,bool,string> edit=(text,id,on)=>(string)build.Invoke(null,new object[]{text,id,on});string original="mods\n{\n    mod = ZombieBuddy,\n    mod = Viewpoint,\n    mod = Other,\n}\nmaps\n{\n map = Keep,\n}\n";string next=edit(original,"surface",true);Check(next.Contains("mod = ViewpointSurface,")&&next.Contains("mod = Other,")&&next.Contains("map = Keep,"),"enable adds only selected addon preserving maps and other mods");Check(edit(next,"surface",false)==original,"disable restores unrelated literal formatting");bool bad=false;try{edit(original,"ViewpointTrueWeathersGameplay",true);}catch{bad=true;}Check(bad,"weather Gameplay cannot be enabled by registry");Check(edit(next,"surface",true)==next,"enabling twice is idempotent");Check(edit(original,"trees",true).Contains("ProjectViewpointNearVegetation"),"tree addon registered");Console.WriteLine("PASS addon activation fixtures");}
 public static void Resolver(){string root=Path.Combine(@"E:\AppCaches\OrangeLauncherExtensions\TestFixtures","resolver-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"steamapps/common/Game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);string folder=Path.Combine(e.Workshop,"3814994364/mods/ViewpointForaging");Directory.CreateDirectory(Path.Combine(folder,"common"));File.WriteAllText(Path.Combine(folder,"common/mod.info"),"id=ViewpointForaging\njavaJarFile=media/java/client/ViewpointForaging.jar\njavaPkgName=vpforage\n");foreach(string part in new[]{"42","42.1","42.21.0","42.99"}){string jar=Path.Combine(folder,part,"media/java/client/ViewpointForaging.jar");Directory.CreateDirectory(Path.GetDirectoryName(jar));File.WriteAllText(jar,part);}var a=ViewpointAddons.Get("foraging");Check(File.ReadAllText(ViewpointAddons.Resolve(e,a,new Version(42,20)).Jar)=="42.1","payload version selection independent of mod.info");Check(File.ReadAllText(ViewpointAddons.Resolve(e,a,new Version(42,21)).Jar)=="42.21.0","minor version matches explicit .0 patch and future excluded");File.WriteAllText(Path.Combine(folder,"common/mod.info"),"id=ViewpointForaging\njavaJarFile=../../escape.jar\njavaPkgName=vpforage\n");bool bad=false;try{ViewpointAddons.Resolve(e,a,new Version(42,21));}catch{bad=true;}Check(bad,"author declared Java path traversal refused");Console.WriteLine("PASS version-specific payload and path confinement");}
 public static int Main(){try{Run();Resolver();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
